// Actual original Config -> routing.NewRoomManagerClient -> typed PSRPC local
// bus/server. Observer only records original published request expiry; no source
// retry arithmetic, request timeout, or construction branch is replaced.
package main
import("bufio";"context";"encoding/json";"fmt";"os";"sync";"time";"github.com/livekit/livekit-server/pkg/config";"github.com/livekit/livekit-server/pkg/routing";pb "github.com/livekit/protocol/livekit";"github.com/livekit/protocol/rpc";"github.com/livekit/protocol/logger";"github.com/livekit/psrpc";"google.golang.org/protobuf/proto")
type observedBus struct{psrpc.MessageBus;mu sync.Mutex;timeouts []int64}
func(b *observedBus)Publish(ctx context.Context,c psrpc.Channel,m proto.Message)error{p:=m.ProtoReflect();f:=p.Descriptor().Fields();sent,expiry:=f.ByName("sent_at"),f.ByName("expiry");if sent!=nil&&expiry!=nil{b.mu.Lock();b.timeouts=append(b.timeouts,p.Get(expiry).Int()-p.Get(sent).Int());b.mu.Unlock()};return b.MessageBus.Publish(ctx,c,m)}
type caseInput struct{ID string `json:"id"`;Attempts int `json:"attempts"`;Timeout string `json:"timeout"`;Errors []string `json:"errors"`;CancelAt int `json:"cancel_at"`;CallerTimeout string `json:"caller_timeout"`;Hold bool `json:"hold_until_expiry"`}
type service struct{mu sync.Mutex;input caseInput;calls int;active int;cancel context.CancelFunc;codes []string}
func(s *service)CreateRoom(ctx context.Context,r *pb.CreateRoomRequest)(*pb.Room,error){s.mu.Lock();s.calls++;index:=s.calls;s.active++;s.mu.Unlock();defer func(){s.mu.Lock();s.active--;s.mu.Unlock()}();if s.input.CancelAt==index{s.cancel()};if s.input.Hold{<-ctx.Done();return nil,ctx.Err()};kind:="success";if index<=len(s.input.Errors){kind=s.input.Errors[index-1]};if kind=="success"{return &pb.Room{Name:r.Name,Sid:"RM_actual_source_result"},nil};return nil,psrpc.NewError(psrpc.ErrorCode(kind),fmt.Errorf("owned source %s",kind))}
func main(){in,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};defer in.Close();scanner:=bufio.NewScanner(in);out:=json.NewEncoder(os.Stdout);for scanner.Scan(){var c caseInput;if e=json.Unmarshal(scanner.Bytes(),&c);e!=nil{panic(e)};cfg,e:=config.NewConfig(fmt.Sprintf("rtc: {node_ip: 127.0.0.1, use_external_ip: false}\nroom:\n  create_room_attempts: %d\n  create_room_timeout: %s\n",c.Attempts,c.Timeout),true,nil,nil);if e!=nil{panic(e)};ctx,cancel:=context.WithTimeout(context.Background(),10*time.Second);bus:=&observedBus{MessageBus:psrpc.NewLocalMessageBus(),timeouts:[]int64{}};svc:=&service{input:c,cancel:cancel};server,e:=rpc.NewTypedRoomManagerServer(svc,bus);if e!=nil{panic(e)};if e=server.RegisterCreateRoomTopic(pb.NodeID("ND_source_owner"));e!=nil{panic(e)};client,e:=routing.NewRoomManagerClient(rpc.ClientParams{Observer:rpc.UnimplementedMetricsObserver{},Bus:bus,PSRPCConfig:rpc.PSRPCConfig{BufferSize:100},Logger:logger.GetDiscardLogger()},cfg.Room);if e!=nil{panic(e)};opts:=[]psrpc.RequestOption{};if c.CallerTimeout!=""{timeout,e:=time.ParseDuration(c.CallerTimeout);if e!=nil{panic(e)};opts=append(opts,psrpc.WithRequestTimeout(timeout))};room,err:=client.CreateRoom(ctx,pb.NodeID("ND_source_owner"),&pb.CreateRoomRequest{Name:"owned-source-room"},opts...);cancel();client.Close();server.Shutdown();svc.mu.Lock();calls,active:=svc.calls,svc.active;svc.mu.Unlock();bus.mu.Lock();timeouts:=append([]int64{},bus.timeouts...);bus.mu.Unlock();code,text:="","";if err!=nil{text=err.Error();if v,ok:=psrpc.GetErrorCode(err);ok{code=string(v)}};if e=out.Encode(map[string]any{"id":c.ID,"configured_attempts":cfg.Room.CreateRoomAttempts,"configured_timeout_ns":int64(cfg.Room.CreateRoomTimeout),"published_timeout_ns":timeouts,"handler_calls":calls,"handler_active_after_shutdown":active,"success":room!=nil&&err==nil,"error_code":code,"error":text});e!=nil{panic(e)}};if e=scanner.Err();e!=nil{panic(e)}}
